SET search_path TO teles, public;
ALTER TABLE daily_rates DROP CONSTRAINT IF EXISTS daily_rates_day_check;
ALTER TABLE daily_rates ADD CONSTRAINT daily_rates_day_check CHECK (day ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$');
DROP INDEX IF EXISTS idx_guests_hotel_identity;
CREATE UNIQUE INDEX idx_guests_hotel_identity ON guests(hotel_id,lower(btrim(name)),regexp_replace(phone,'[^0-9]','','g')) WHERE phone<>'';
ALTER TABLE operators ADD COLUMN IF NOT EXISTS role text NOT NULL DEFAULT 'admin' CHECK (role IN ('admin','reception'));
ALTER TABLE operators ADD COLUMN IF NOT EXISTS name text NOT NULL DEFAULT '';
ALTER TABLE operators ADD COLUMN IF NOT EXISTS active integer NOT NULL DEFAULT 1 CHECK (active IN (0,1));
ALTER TABLE entries ADD COLUMN IF NOT EXISTS card_brand text NOT NULL DEFAULT '';
ALTER TABLE entries ADD COLUMN IF NOT EXISTS card_auth text NOT NULL DEFAULT '';
ALTER TABLE entries ADD COLUMN IF NOT EXISTS reconciled_at text;
ALTER TABLE entries ADD COLUMN IF NOT EXISTS reconciled_by text;
ALTER TABLE entries ADD COLUMN IF NOT EXISTS voided_at text;
ALTER TABLE entries ADD COLUMN IF NOT EXISTS voided_by text;
ALTER TABLE entries ADD COLUMN IF NOT EXISTS quantity integer NOT NULL DEFAULT 1;
ALTER TABLE entries ADD COLUMN IF NOT EXISTS unit_price integer;
ALTER TABLE reservations ADD COLUMN IF NOT EXISTS cancellation_settlement text;
ALTER TABLE reservations ADD COLUMN IF NOT EXISTS cancellation_amount integer NOT NULL DEFAULT 0;
ALTER TABLE reservation_nights ADD COLUMN IF NOT EXISTS room_id text REFERENCES rooms(id);
ALTER TABLE booking_requests ADD COLUMN IF NOT EXISTS quoted_nights jsonb;
CREATE TABLE IF NOT EXISTS room_moves (id text PRIMARY KEY, hotel_id text NOT NULL REFERENCES hotels(id),reservation_id text NOT NULL REFERENCES reservations(id),from_room text NOT NULL REFERENCES rooms(id), to_room text NOT NULL REFERENCES rooms(id),day text NOT NULL, actor text NOT NULL, created text NOT NULL);
CREATE INDEX IF NOT EXISTS idx_room_moves_reservation ON room_moves(reservation_id,day,created);
CREATE TABLE IF NOT EXISTS guest_records (reservation_id text PRIMARY KEY REFERENCES reservations(id), hotel_id text NOT NULL REFERENCES hotels(id),data jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(data)='object'),updated text NOT NULL, actor text NOT NULL);
ALTER TABLE room_moves ENABLE ROW LEVEL SECURITY;
ALTER TABLE guest_records ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON room_moves,guest_records FROM PUBLIC,anon,authenticated;
CREATE INDEX IF NOT EXISTS idx_nights_room_day ON reservation_nights(room_id,day);
CREATE OR REPLACE FUNCTION teles.room_available(h text, q text, arrival text, departure text, except_reservation text DEFAULT '', except_request text DEFAULT '') RETURNS boolean LANGUAGE sql STABLE SET search_path = teles, pg_temp AS $$ SELECT NOT EXISTS (SELECT 1 FROM reservations r WHERE r.hotel_id=h AND r.id<>except_reservation AND r.status IN ('confirmed','checked_in') AND r.checkin<departure AND r.checkout>arrival AND (EXISTS(SELECT 1 FROM reservation_nights n WHERE n.reservation_id=r.id AND COALESCE(n.room_id,r.room_id)=q AND n.day>=arrival AND n.day<departure) OR (r.room_id=q AND NOT EXISTS(SELECT 1 FROM reservation_nights n WHERE n.reservation_id=r.id)))) AND NOT EXISTS (SELECT 1 FROM booking_requests b WHERE b.hotel_id=h AND b.room_id=q AND b.id<>except_request AND b.status='awaiting_payment' AND b.hold_until>now() AND b.checkin<departure AND b.checkout>arrival) $$;
REVOKE ALL ON FUNCTION teles.room_available(text,text,text,text,text,text) FROM PUBLIC,anon,authenticated;
RESET search_path;;
